<?php
$uid = (int)$u['id']; $id = (int)($_GET['id'] ?? 0);
handle('es_create', function () use ($uid) { $ms = []; foreach ((array)($_POST['mt'] ?? []) as $k => $tt) $ms[] = ['title' => $tt, 'amount' => $_POST['ma'][$k] ?? '', 'due' => $_POST['md'][$k] ?? '']; $e = Escrow::create($uid, (string)$_POST['seller'], (string)$_POST['title'], ($_POST['currency'] ?? 'BDT') === 'USD' ? 'USD' : 'BDT', $ms); flash('ok', 'Escrow contract created. Fund each milestone when you are ready.'); redirect(url('escrow', ['id' => $e])); });
handle('es_fund', function () use ($uid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); Escrow::fund($uid, (int)$_POST['ms'], idem_key()); return 'Milestone funded. The money is now held in the escrow ledger account.'; });
handle('es_submit', function () use ($uid) { Escrow::submit($uid, (int)$_POST['ms']); return 'Work submitted for the buyer to review.'; });
handle('es_close', function () use ($uid) { $mode = $_POST['mode'] === 'refund' ? 'refund' : 'release'; Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); Escrow::close($uid, (int)$_POST['ms'], $mode); return $mode === 'release' ? 'Funds released to the seller.' : 'Funds refunded to the buyer.'; });
handle('es_dispute', function () use ($uid) { $d = Disputes::open($uid, null, (int)$_POST['ms'], (string)$_POST['reason']); flash('ok', 'Dispute opened. Add evidence notes so the administrator can decide.'); redirect(url('disputes', ['id' => $d])); });
if ($id) {
  $e = row('SELECT e.*, b.name bname, s.name sname FROM escrows e JOIN users b ON b.id=e.buyer_id JOIN users s ON s.id=e.seller_id WHERE e.id=? AND (e.buyer_id=? OR e.seller_id=?)', [$id, $uid, $uid]);
  if (!$e) { http_response_code(404); echo card('', empty_state('Escrow not found.')); return; }
  $buyer = (int)$e['buyer_id'] === $uid; $ms = rows('SELECT * FROM escrow_milestones WHERE escrow_id=? ORDER BY seq', [$id]); $cur = $e['currency']; $rows = [];
  foreach ($ms as $m) { $a = ''; $pin = '<input name="pin" type="password" inputmode="numeric" maxlength="6" placeholder="PIN" required style="min-width:80px" aria-label="PIN">'; $h = '<input type="hidden" name="ms" value="' . (int)$m['id'] . '">';
    if ($buyer && $m['status'] === 'pending') $a .= form_start('es_fund', 'class="inline"') . $h . '<div class="row">' . $pin . btn('Fund', 'sm') . '</div></form>';
    if (!$buyer && $m['status'] === 'funded') $a .= form_start('es_submit', 'class="inline"') . $h . btn('Submit work', 'sm') . '</form>';
    if ($buyer && in_array($m['status'], ['funded', 'submitted'], true)) $a .= form_start('es_close', 'class="inline"') . $h . '<input type="hidden" name="mode" value="release"><div class="row">' . $pin . btn('Release', 'sm') . '</div></form>';
    if (!$buyer && in_array($m['status'], ['funded', 'submitted'], true)) $a .= form_start('es_close', 'class="inline"') . $h . '<input type="hidden" name="mode" value="refund"><div class="row">' . $pin . btn('Refund buyer', 'secondary sm') . '</div></form>';
    if (in_array($m['status'], ['funded', 'submitted'], true)) $a .= '<details><summary class="hint">Problem? Open a dispute</summary>' . form_start('es_dispute') . $h . '<textarea name="reason" rows="2" required minlength="5" maxlength="255" placeholder="What went wrong?" aria-label="Reason"></textarea>' . btn('Open dispute', 'secondary sm') . '</form></details>';
    $rows[] = [(int)$m['seq'], e($m['title']) . ($m['due_date'] ? '<div class="hint">due ' . e(fdate($m['due_date'], false)) . '</div>' : ''), mny($m['amount'], $cur), badge($m['status']), $a]; }
  $tl = rows("SELECT * FROM timeline_events WHERE entity_type='escrow' AND entity_id=? ORDER BY id", [$id]); $tls = '<ul class="timeline">'; foreach ($tl as $x) $tls .= '<li><strong>' . e(ucfirst($x['event'])) . '</strong> <span class="hint">' . e(fdate($x['created_at'])) . '</span><div class="hint">' . e($x['note']) . '</div></li>'; $tls .= '</ul>';
  echo page_head($e['title'], $e['ref'] . ' &middot; buyer ' . $e['bname'] . ' &middot; seller ' . $e['sname'], badge($e['status']) . ' <a class="btn secondary sm" href="' . e(url('escrow')) . '">' . e(t('Back')) . '</a>') . '<div class="alert info">Funds for funded milestones are held in a separate escrow ledger account, not in either wallet. A milestone is closed by release (seller paid, ' . e(setting('merchant_fee_percent')) . '% fee), refund, or an administrator\'s dispute decision. This is a ledger rule inside the demo, not a blockchain or smart contract.</div>' . card('Milestones', tbl(['#', 'Milestone', ['Amount', 'num'], 'Status', 'Actions'], $rows)) . '<div style="height:16px"></div>' . card('Timeline', $tls); return;
}
$list = rows('SELECT e.*, b.name bname, s.name sname, (SELECT COALESCE(SUM(amount),0) FROM escrow_milestones WHERE escrow_id=e.id) total FROM escrows e JOIN users b ON b.id=e.buyer_id JOIN users s ON s.id=e.seller_id WHERE e.buyer_id=? OR e.seller_id=? ORDER BY e.id DESC', [$uid, $uid]); $rows = [];
foreach ($list as $e) $rows[] = ['<a href="' . e(url('escrow', ['id' => $e['id']])) . '"><strong>' . e($e['title']) . '</strong></a><div class="hint">' . e($e['ref']) . '</div>', (int)$e['buyer_id'] === $uid ? 'Buyer (you) / ' . e($e['sname']) : e($e['bname']) . ' / Seller (you)', mny($e['total'], $e['currency']), badge($e['status'])];
$mrows = ''; for ($k = 0; $k < 3; $k++) $mrows .= '<div class="row"><div style="flex:3 1 140px"><input name="mt[]" placeholder="Milestone ' . ($k + 1) . '" maxlength="150" aria-label="Milestone title"></div><div><input name="ma[]" placeholder="Amount" inputmode="decimal" aria-label="Amount"></div><div><input type="date" name="md[]" aria-label="Due date"></div></div><div style="height:6px"></div>';
echo page_head('Escrow', 'Hold payment for freelance or marketplace work and release it milestone by milestone.') . '<div class="grid g-main">' . card('Your escrow contracts', tbl(['Contract', 'Parties', ['Total', 'num'], 'Status'], $rows, 'No escrow contracts yet.')) . card('New contract (you are the buyer)', form_start('es_create') . field('Title', 'title', 'text', '', 'required maxlength="150"') . field('Seller', 'seller', 'text', '', 'required placeholder="email or phone"') . select('Currency', 'currency', ['BDT' => 'BDT', 'USD' => 'USD'], 'BDT') . '<label>Milestones</label>' . $mrows . btn('Create contract') . '</form>') . '</div>';
